-- orders: key stats
SELECT COUNT(*) AS cnt, MIN("ORDER_ID") AS lo, MAX("ORDER_ID") AS hi FROM "APP_OWNER"."ORDERS"

-- orders: range chunk fingerprints
SELECT b, COUNT(*) AS cnt, SUM(h) AS hsum FROM (SELECT FLOOR(("ORDER_ID" - :lo) / :w) AS b, TO_NUMBER(SUBSTR(RAWTOHEX(STANDARD_HASH(CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN RTRIM("CUSTOMER_CODE") IS NULL THEN '~' ELSE LENGTHB(RTRIM("CUSTOMER_CODE")) || ':' || RTRIM("CUSTOMER_CODE") END || CASE WHEN "STATUS" IS NULL THEN '~' ELSE LENGTHB("STATUS") || ':' || "STATUS" END || CASE WHEN "NOTE" IS NULL THEN '~' ELSE LENGTHB("NOTE") || ':' || "NOTE" END || CASE WHEN "AMOUNT" IS NULL THEN '~' ELSE LENGTHB(REGEXP_REPLACE(TO_CHAR("AMOUNT", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.')) || ':' || REGEXP_REPLACE(TO_CHAR("AMOUNT", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.') END || CASE WHEN "DISCOUNT_RATE" IS NULL THEN '~' ELSE LENGTHB(REGEXP_REPLACE(TO_CHAR("DISCOUNT_RATE", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.')) || ':' || REGEXP_REPLACE(TO_CHAR("DISCOUNT_RATE", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.') END || CASE WHEN "CREATED_ON" IS NULL THEN '~' ELSE '19' || ':' || TO_CHAR("CREATED_ON", 'YYYY-MM-DD"T"HH24:MI:SS') END || CASE WHEN "SHIPPED_AT" IS NULL THEN '~' ELSE '26' || ':' || TO_CHAR("SHIPPED_AT", 'YYYY-MM-DD"T"HH24:MI:SS.FF6') END || CASE WHEN "UPDATED_AT" IS NULL THEN '~' ELSE '27' || ':' || TO_CHAR(SYS_EXTRACT_UTC("UPDATED_AT"), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"') END, 'MD5')), 1, 15), 'XXXXXXXXXXXXXXX') AS h FROM "APP_OWNER"."ORDERS" WHERE "ORDER_ID" BETWEEN :lo AND :hi) s GROUP BY b ORDER BY b

-- orders: leaf row digests (2 ranges)
SELECT "ORDER_ID" AS k, LOWER(RAWTOHEX(STANDARD_HASH(CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN RTRIM("CUSTOMER_CODE") IS NULL THEN '~' ELSE LENGTHB(RTRIM("CUSTOMER_CODE")) || ':' || RTRIM("CUSTOMER_CODE") END || CASE WHEN "STATUS" IS NULL THEN '~' ELSE LENGTHB("STATUS") || ':' || "STATUS" END || CASE WHEN "NOTE" IS NULL THEN '~' ELSE LENGTHB("NOTE") || ':' || "NOTE" END || CASE WHEN "AMOUNT" IS NULL THEN '~' ELSE LENGTHB(REGEXP_REPLACE(TO_CHAR("AMOUNT", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.')) || ':' || REGEXP_REPLACE(TO_CHAR("AMOUNT", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.') END || CASE WHEN "DISCOUNT_RATE" IS NULL THEN '~' ELSE LENGTHB(REGEXP_REPLACE(TO_CHAR("DISCOUNT_RATE", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.')) || ':' || REGEXP_REPLACE(TO_CHAR("DISCOUNT_RATE", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.') END || CASE WHEN "CREATED_ON" IS NULL THEN '~' ELSE '19' || ':' || TO_CHAR("CREATED_ON", 'YYYY-MM-DD"T"HH24:MI:SS') END || CASE WHEN "SHIPPED_AT" IS NULL THEN '~' ELSE '26' || ':' || TO_CHAR("SHIPPED_AT", 'YYYY-MM-DD"T"HH24:MI:SS.FF6') END || CASE WHEN "UPDATED_AT" IS NULL THEN '~' ELSE '27' || ':' || TO_CHAR(SYS_EXTRACT_UTC("UPDATED_AT"), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"') END, 'MD5'))) AS d FROM "APP_OWNER"."ORDERS" WHERE "ORDER_ID" BETWEEN :lo0 AND :hi0 OR "ORDER_ID" BETWEEN :lo1 AND :hi1

-- orders: encoded fields by key (2 keys)
SELECT "ORDER_ID" AS k, CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END AS c0, CASE WHEN RTRIM("CUSTOMER_CODE") IS NULL THEN '~' ELSE LENGTHB(RTRIM("CUSTOMER_CODE")) || ':' || RTRIM("CUSTOMER_CODE") END AS c1, CASE WHEN "STATUS" IS NULL THEN '~' ELSE LENGTHB("STATUS") || ':' || "STATUS" END AS c2, CASE WHEN "NOTE" IS NULL THEN '~' ELSE LENGTHB("NOTE") || ':' || "NOTE" END AS c3, CASE WHEN "AMOUNT" IS NULL THEN '~' ELSE LENGTHB(REGEXP_REPLACE(TO_CHAR("AMOUNT", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.')) || ':' || REGEXP_REPLACE(TO_CHAR("AMOUNT", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.') END AS c4, CASE WHEN "DISCOUNT_RATE" IS NULL THEN '~' ELSE LENGTHB(REGEXP_REPLACE(TO_CHAR("DISCOUNT_RATE", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.')) || ':' || REGEXP_REPLACE(TO_CHAR("DISCOUNT_RATE", 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), '^(-?)\.', '\10.') END AS c5, CASE WHEN "CREATED_ON" IS NULL THEN '~' ELSE '19' || ':' || TO_CHAR("CREATED_ON", 'YYYY-MM-DD"T"HH24:MI:SS') END AS c6, CASE WHEN "SHIPPED_AT" IS NULL THEN '~' ELSE '26' || ':' || TO_CHAR("SHIPPED_AT", 'YYYY-MM-DD"T"HH24:MI:SS.FF6') END AS c7, CASE WHEN "UPDATED_AT" IS NULL THEN '~' ELSE '27' || ':' || TO_CHAR(SYS_EXTRACT_UTC("UPDATED_AT"), 'YYYY-MM-DD"T"HH24:MI:SS.FF6"Z"') END AS c8 FROM "APP_OWNER"."ORDERS" WHERE "ORDER_ID" IN (:k0, :k1)

-- order_documents: bucket fingerprints, SHA-256
SELECT b, COUNT(*) AS cnt, SUM(h) AS hsum FROM (SELECT MOD(TO_NUMBER(SUBSTR(RAWTOHEX(STANDARD_HASH(CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN "DOC_NO" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("DOC_NO", 'TM9')) || ':' || TO_CHAR("DOC_NO", 'TM9') END, 'MD5')), 1, 8), 'XXXXXXXX'), :n) AS b, TO_NUMBER(SUBSTR(RAWTOHEX(STANDARD_HASH(CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN "DOC_NO" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("DOC_NO", 'TM9')) || ':' || TO_CHAR("DOC_NO", 'TM9') END || CASE WHEN "BODY" IS NULL THEN '~' ELSE '64:' || LOWER(RAWTOHEX(SYS.DBMS_CRYPTO.HASH("BODY", 4))) END || CASE WHEN "CREATED_AT" IS NULL THEN '~' ELSE '26' || ':' || TO_CHAR("CREATED_AT", 'YYYY-MM-DD"T"HH24:MI:SS.FF6') END, 'SHA256')), 1, 15), 'XXXXXXXXXXXXXXX') AS h FROM "APP_OWNER"."ORDER_DOCUMENTS") s GROUP BY b ORDER BY b

-- order_documents: bucket leaf (1 bucket), empty strings as NULL
SELECT CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN "DOC_NO" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("DOC_NO", 'TM9')) || ':' || TO_CHAR("DOC_NO", 'TM9') END AS k, LOWER(RAWTOHEX(STANDARD_HASH(CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN "DOC_NO" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("DOC_NO", 'TM9')) || ':' || TO_CHAR("DOC_NO", 'TM9') END || CASE WHEN ("BODY" IS NULL OR DBMS_LOB.GETLENGTH("BODY") = 0) THEN '~' ELSE '32:' || LOWER(RAWTOHEX(SYS.DBMS_CRYPTO.HASH("BODY", 2))) END || CASE WHEN "CREATED_AT" IS NULL THEN '~' ELSE '26' || ':' || TO_CHAR("CREATED_AT", 'YYYY-MM-DD"T"HH24:MI:SS.FF6') END, 'MD5'))) AS d FROM "APP_OWNER"."ORDER_DOCUMENTS" WHERE MOD(TO_NUMBER(SUBSTR(RAWTOHEX(STANDARD_HASH(CASE WHEN "ORDER_ID" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("ORDER_ID", 'TM9')) || ':' || TO_CHAR("ORDER_ID", 'TM9') END || CASE WHEN "DOC_NO" IS NULL THEN '~' ELSE LENGTHB(TO_CHAR("DOC_NO", 'TM9')) || ':' || TO_CHAR("DOC_NO", 'TM9') END, 'MD5')), 1, 8), 'XXXXXXXX'), :n) IN (:b0)

-- customers: client-side raw rows
SELECT "CUSTOMER_CODE", "FULL_NAME", "BIRTH_DATE", "SEGMENT" FROM "APP_OWNER"."CUSTOMERS"
